// Writes the Expo app's screens from out/screens.json: every phone and tablet screen as native
// React Native views (mobile/src/screens/<key>.tsx), a registry, and the fonts they use.
// Live screens: when mobile/src/live/<key>.tsx exists (hand-written from the generated file, with real
// data and actions in the same Frame/Tap runtime), the registry opens it instead of the generated one.
// Usage: node gen-mobile.js   (after node extract.js)
const fs = require('fs');
const path = require('path');

const REPO = path.resolve(__dirname, '..', '..');
const MOB = path.join(REPO, 'mobile', 'src');
const DATA = JSON.parse(fs.readFileSync(path.join(__dirname, 'out', 'screens.json'), 'utf8'));
const frames = DATA.frames;
const byKey = Object.fromEntries(frames.map(f => [f.key, f]));
const mobile = frames.filter(f => f.plat !== 'desktop');
const FACE = { store: 'Lodestar Store', plan: 'Lodestar Plan', dock: 'Lodestar Dock', run: 'Lodestar Run', admin: 'Lodestar Admin' };
const HEADER = '// Generated by tools/screengen from Designing/pages. Do not edit by hand: change the design and run `npm run screens` in tools/screengen.\n';
const write = (p, s) => { fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, s); };

// ---------- fonts
const FAM = { 'Inter': 'Inter', 'Plus Jakarta Sans': 'PlusJakartaSans', 'JetBrains Mono': 'JetBrainsMono', 'Noto Sans Sinhala': 'NotoSansSinhala', 'Noto Sans Tamil': 'NotoSansTamil' };
const PKG = { Inter: 'inter', PlusJakartaSans: 'plus-jakarta-sans', JetBrainsMono: 'jetbrains-mono', NotoSansSinhala: 'noto-sans-sinhala', NotoSansTamil: 'noto-sans-tamil' };
const WT = { 400: '400Regular', 500: '500Medium', 600: '600SemiBold', 700: '700Bold', 800: '800ExtraBold' };
const usedFonts = new Set(['Inter_600SemiBold', 'Inter_700Bold']);   // the runtime toast
function fontName(ff, fw, italic) {
  const fam = FAM[ff] || 'Inter';
  const w = Math.min(800, Math.max(400, Math.round((fw || 400) / 100) * 100));
  const name = `${fam}_${WT[w]}${italic && /^(Inter|PlusJakartaSans|JetBrainsMono)$/.test(fam) ? '_Italic' : ''}`;
  usedFonts.add(name);
  return name;
}

// ---------- styles
const SCRIPT = { si: /[඀-෿]/, ta: /[஀-௿]/ };
function viewStyle(s) {
  const o = {};
  for (const [k, v] of Object.entries(s || {})) {
    if (k === 'backgroundImage' || k === 'grad') continue;
    o[k] = v;
  }
  return o;
}
function textStyle(ts, parentFull) {
  // resolve against the parent run so weight/family changes pick the right font file
  const full = { ...(parentFull || {}), ...ts };
  const o = {};
  for (const [k, v] of Object.entries(ts)) {
    if (k === 'ff' || k === 'fw' || k === 'fontStyle') continue;
    o[k] = v;
  }
  if (!parentFull || 'ff' in ts || 'fw' in ts || 'fontStyle' in ts) o.fontFamily = fontName(full.ff, full.fw, full.fontStyle === 'italic');
  if (full.fontStyle === 'italic' && !/Italic/.test(o.fontFamily || '')) o.fontStyle = 'italic';
  return { o, full };
}
const OUTER = /^(flex|flexGrow|flexShrink|flexBasis|alignSelf|margin|marginTop|marginRight|marginBottom|marginLeft|width|height|minWidth|minHeight|maxWidth|maxHeight|position|top|right|bottom|left|zIndex|backgroundColor|borderRadius|borderTopLeftRadius|borderTopRightRadius|borderBottomLeftRadius|borderBottomRightRadius|borderWidth|borderColor|borderTopWidth|borderRightWidth|borderBottomWidth|borderLeftWidth|borderTopColor|borderRightColor|borderBottomColor|borderLeftColor|borderStyle|boxShadow|opacity|overflow|transform)$/;

function genScreen(f) {
  const styles = new Map(); // json -> name
  const svgs = new Map();   // xml -> name
  const imports = new Set(['Frame']);
  const rn = new Set(['View']);
  const sname = (obj, prefix) => {
    const j = JSON.stringify(obj);
    if (!styles.has(j)) styles.set(j, prefix + styles.size);
    return 's.' + styles.get(j);
  };
  const ind = n => '  '.repeat(n);
  const esc = t => JSON.stringify(t);

  const grads = new Map();  // gradient json -> name
  function styleExpr(s) {
    const vs = viewStyle(s);
    return Object.keys(vs).length ? sname(vs, 'v') : '';
  }
  // gradient backdrop drawn behind the box's children, clipped to its corners
  function gradLayer(s, d) {
    if (!s || !s.grad) return '';
    imports.add('Grad');
    const j = JSON.stringify(s.grad);
    if (!grads.has(j)) grads.set(j, 'G' + grads.size);
    const rad = {};
    for (const k of ['borderRadius', 'borderTopLeftRadius', 'borderTopRightRadius', 'borderBottomRightRadius', 'borderBottomLeftRadius']) if (s[k]) rad[k] = s[k];
    return '\n' + ind(d + 1) + `<Grad g={${grads.get(j)}}${Object.keys(rad).length ? ` style={${sname(rad, 'v')}}` : ''} />`;
  }

  function textRuns(t, parentFull, d) {
    const { o, full } = textStyle(t.ts, parentFull);
    const out = [];
    for (const c of t.c) {
      if (typeof c === 'string') {
        // Sinhala / Tamil runs need their own font file
        if (SCRIPT.si.test(c) || SCRIPT.ta.test(c)) {
          const fam = SCRIPT.si.test(c) ? 'Noto Sans Sinhala' : 'Noto Sans Tamil';
          const fs2 = { fontFamily: fontName(fam, full.fw) };
          out.push(`<Text style={${sname(fs2, 't')}}>{${esc(c)}}</Text>`);
        } else out.push(`{${esc(c)}}`);
      } else if (c.k === 'T') {
        out.push(textNode(c, full, d + 1, true));
      } else {
        out.push(node(c, d + 1));
      }
    }
    return { o, inner: out.join(''), full };
  }
  function textNode(t, parentFull, d, nested) {
    rn.add('Text');
    const { o, inner } = textRuns(t, parentFull, d);
    const st = Object.keys(o).length ? ` style={${sname(o, 't')}}` : '';
    const lines = t.lines ? ` numberOfLines={${t.lines}}${t.lines === 1 ? '' : ''}` : '';
    if (t.lk) { imports.add('TapText'); return `<TapText lk=${esc(t.lk)}${st}>${inner}</TapText>`; }
    return `<Text${st}${lines}>${inner}</Text>`;
  }

  function node(n, d) {
    if (typeof n === 'string') return `{${esc(n)}}`;
    if (n.k === 'T') return '\n' + ind(d) + textNode(n, null, d, false);
    if (n.k === 'S') {
      imports.add('Icon');
      if (!svgs.has(n.xml)) svgs.set(n.xml, 'X' + svgs.size);
      const { width, height, ...rest } = n.s;
      const st = styleExpr(rest);
      const icon = `<Icon xml={${svgs.get(n.xml)}} width={${width}} height={${height}}${st ? ` style={${st}}` : ''} />`;
      if (n.lk) { imports.add('Tap'); return '\n' + ind(d) + `<Tap lk=${esc(n.lk)}>${icon}</Tap>`; }
      return '\n' + ind(d) + icon;
    }
    const kids = gradLayer(n.s, d) + (n.c || []).map(c => node(c, d + 1)).join('');
    const close = kids ? `>${kids}\n${ind(d)}` : null;
    if (n.scroll) {
      imports.add('Scroll');
      const outer = {}, inner = {};
      for (const [k, v] of Object.entries(viewStyle(n.s))) (OUTER.test(k) ? outer : inner)[k] = v;
      delete outer.overflow;
      const a = Object.keys(outer).length ? ` style={${sname(outer, 'v')}}` : '';
      const b = Object.keys(inner).length ? ` contentStyle={${sname(inner, 'v')}}` : '';
      return '\n' + ind(d) + `<Scroll${a}${b}${close ? close + '</Scroll>' : ' />'}`;
    }
    const st = styleExpr(n.s);
    const sa = st ? ` style={${st}}` : '';
    if (n.lk || n.speak) {
      imports.add('Tap');
      const lk = n.lk ? ` lk=${esc(n.lk)}` : '';
      const say = n.speak ? ` say={${esc(n.speak)}}` : '';
      const hasTap = x => !!x && typeof x === 'object' && (!!x.lk || !!x.speak || (x.c || []).some(hasTap));
      const group = (n.c || []).some(hasTap) ? ' group' : '';
      return '\n' + ind(d) + `<Tap${lk}${say}${group}${sa}${close ? close + '</Tap>' : ' />'}`;
    }
    return '\n' + ind(d) + `<View${sa}${close ? close + '</View>' : ' />'}`;
  }

  // nav table
  const links = {};
  for (const [code, l] of Object.entries(f.links)) {
    const dest = l.to && byKey[l.to];
    if (!dest) continue;
    links[code] = dest.plat === 'desktop' ? { app: FACE[dest.app] + ' (desktop)', screen: dest.name.replace(/\s*·\s*desktop$/i, '') } : { to: dest.key, kind: l.kind };
  }
  const one = key => { const d = byKey[key]; if (!d) return undefined; return d.plat === 'desktop' ? { app: FACE[d.app] + ' (desktop)', screen: d.name.replace(/\s*·\s*desktop$/i, '') } : { to: d.key }; };
  const nav = { links };
  if (f.auto) nav.auto = one(f.auto);
  if (f.whole) nav.whole = one(f.whole);

  const root = f.tree;
  const rootStyle = viewStyle(root.s);
  delete rootStyle.flex; rootStyle.flex = 1;
  const rootRef = sname(rootStyle, 'v');
  const body = gradLayer(root.s, 2) + (root.c || []).map(c => node(c, 3)).join('');
  const comp = 'Screen' + f.key.split('-').map(w => w[0].toUpperCase() + w.slice(1)).join('').replace(/^(\d)/, '_$1');
  const styleSrc = [...styles.entries()].map(([j, name]) => `  ${name}: ${j},`).join('\n');
  const svgSrc = [...svgs.entries()].map(([xml, name]) => `const ${name} = ${esc(xml)};`)
    .concat([...grads.entries()].map(([j, name]) => `const ${name}: GradSpec[] = ${j};`)).join('\n');
  return `${HEADER}// ${f.name} (${f.board}, ${f.plat})
import { ${[...rn].sort().join(', ')}, StyleSheet } from 'react-native';
import { ${[...imports].sort().join(', ')}, type ScreenNav${grads.size ? ', type GradSpec' : ''} } from '@/lodestar/runtime';

const nav: ScreenNav = ${JSON.stringify(nav)};

export default function ${comp}() {
  return (
    <Frame bg=${esc(f.bg)} nav={nav} style={${rootRef}}>${body}
    </Frame>
  );
}

${svgSrc}

const s = StyleSheet.create({
${styleSrc}
});
`;
}

// ---------- live screens (src/live/<key>.tsx replaces the generated screen in the registry)
const LIVE_DIR = path.join(MOB, 'live');
const live = new Set(fs.existsSync(LIVE_DIR) ? fs.readdirSync(LIVE_DIR).filter(f => /^[a-z0-9-]+\.tsx$/.test(f)).map(f => f.slice(0, -4)) : []);
for (const k of live) if (!byKey[k] || byKey[k].plat === 'desktop') console.warn(`live/${k}.tsx does not match a phone or tablet screen; ignored`);
const liveKeys = mobile.map(f => f.key).filter(k => live.has(k));

// ---------- write
fs.rmSync(path.join(MOB, 'screens'), { recursive: true, force: true });
for (const f of mobile) write(path.join(MOB, 'screens', f.key + '.tsx'), genScreen(f));

write(path.join(MOB, 'screens', 'registry.ts'), `${HEADER}/* eslint-disable @typescript-eslint/no-require-imports */
import type { ComponentType } from 'react';

// Loaded on first use so the app starts fast. Keys in LIVE open src/live/<key>.tsx (real data).
export const SCREENS: Record<string, () => ComponentType> = {
${mobile.map(f => `  ${JSON.stringify(f.key)}: () => require('${live.has(f.key) ? '../live/' : './'}${f.key}').default,`).join('\n')}
};

export const LIVE: string[] = ${JSON.stringify(liveKeys)};

export type ScreenEntry = { key: string; id: string; name: string };
export const FACES: { app: string; title: string; device: 'phone' | 'tablet'; start: string; screens: ScreenEntry[] }[] = ${JSON.stringify(
  (() => {
    const START = { SMp: 'SM-04', DSPp: 'DSP-25', LDp: 'LD-05', LDt: 'LD-20', DRp: 'DR-05' };
    const groups = {};
    for (const f of mobile) {
      const g = f.id.split('-')[0] + (f.plat === 'phone' ? 'p' : 't');
      (groups[g] = groups[g] || { app: f.app, title: FACE[f.app] + (f.plat === 'tablet' ? ' · tablet' : ''), device: f.plat, start: '', screens: [] }).screens.push({ key: f.key, id: f.id, name: f.name.replace(/\s*·\s*(phone|tablet)$/i, '') });
    }
    for (const [g, v] of Object.entries(groups)) v.start = (mobile.find(f => f.id === START[g] && (f.plat === 'phone' ? 'p' : 't') === g.slice(-1)) || byKey[v.screens[0].key]).key;
    return ['SMp', 'DSPp', 'LDp', 'LDt', 'DRp'].map(g => groups[g]).filter(Boolean);
  })(), null, 2)};

export const FLOWS: { name: string; key: string }[] = ${JSON.stringify(
  [['Happy path · from the dock', 'ld-01-dock-queue'], ...DATA.starts.filter(s => /^\d/.test(s[0])).map(s => {
    const f = mobile.find(x => x.id === s[1] && (!s[2] || x.name.startsWith(s[2])));
    return f ? [s[0].replace(/^\d\s*/, ''), f.key] : null;
  }).filter(Boolean)].map(([name, key]) => ({ name, key })), null, 2)};
`);

const fonts = [...usedFonts].sort();
const byPkg = {};
for (const n of fonts) { const fam = n.split('_')[0]; (byPkg[fam] = byPkg[fam] || []).push(n); }
write(path.join(MOB, 'lodestar', 'fonts.ts'), `${HEADER}${Object.entries(byPkg).map(([fam, ns]) => `import { ${ns.join(', ')} } from '@expo-google-fonts/${PKG[fam]}';`).join('\n')}

export const FONTS = { ${fonts.join(', ')} };
`);
console.log(`mobile: ${mobile.length} screens (${liveKeys.length} live), ${fonts.length} font files`);
